"""Conservative relevance to the confirmed Kaluga clinic profile, without AI."""
import re

VERSION=3
PROFILE={
 'region':'Калуга, Калужская область',
 'services':['ОМС','МРТ','КТ','Рентген','УЗИ','Функциональная диагностика','Забор анализов','Анестезия','Дети','Дневной стационар','Терапия','Неврология','Кардиология','Эндокринология','Гастроэнтерология','Гинекология','Урология','Пульмонология','Травматология','Физиотерапия'],
 'equipment':['Siemens Magnetom Harmony 1.0T','Toshiba Aquilion 64'],
 'basis':'Услуги на evromed-kaluga.ru и сведения владельца; Калуга без других филиалов.'}

RULES={
 'ОМС':r'\bомс\b|обязательн\w*\s+(?:социальн\w*\s+)?медицинск\w*\s+страхован|тарифн\w*\s+соглашен|территориальн\w*\s+программ\w*\s+государственн\w*\s+гаранти|программ\w*\s+государственн\w*\s+гаранти\w*\s+бесплатн',
 'МРТ / КТ':r'\bмрт\b|\b(?:кт|скт)\b|томограф|магнитно.{0,3}резонанс|рентген|радиационн\w*\s+(?:безопасност|контрол)|дозиметр|ионизирующ|magnetom\s+harmony|aquilion\s*64|контрастн\w*\s+(?:препарат|средств)',
 'Наркоз':r'анестези|наркоз|седац|реанимац|анестетик',
 'Дневной стационар':r'дневн\w*\s+стационар|стационарозамещающ',
 'Анализы':r'клинико.{0,3}лаборатор|лабораторн\w*\s+диагност|забор\w*\s+(?:биоматериал|кров)|биоматериал|медицинск\w*\s+лаборатор|пцр.{0,30}(?:исследован|инфекц)|функциональн\w*\s+диагност|ультразвуков\w*\s+(?:диагност|исследован)|\bузи\b',
 'Работа центра':r'медицинск\w*\s+(?:помощ|услуг|деятельност|организац|работник|издел|оборудован|осмотр)|охран\w*\s+здоровья|лечебн\w*\s+учрежден|врачебн\w*\s+тайн|права?\s+пациент|информированн\w*\s+(?:добровольн\w*\s+)?согласи|обращен\w*\s+лекарствен|хранен\w*\s+лекарствен|безопасност\w*\s+лекарствен|лицензирован\w*\s+медицинск|медицинск\w*\s+отход|медицинск\w*\s+сестр|сестринск\w*\s+дел|аккредитац\w*\s+специалист',
 'Общие требования':r'трудов\w*\s+кодекс|охран\w*\s+труда|трудов\w*\s+отношен|рабоч\w*\s+врем|праздничн\w*\s+и\s+выходн|перенос\w*\s+выходн|персональн\w*\s+данн|контрольно.{0,3}кассов|кассов\w*\s+(?:техник|аппарат|чек)|\bусн\b|упрощенн\w*\s+систем\w*\s+налогооблож|налог\w*\s+на\s+прибыл|налог\w*\s+на\s+добавленн\w*\s+стоимост|страхов\w*\s+взнос|налог\w*\s+на\s+доход\w*\s+физическ|\bндфл\b|электронн\w*\s+документооборот|пожарн\w*\s+безопасност|защит\w*\s+прав\w*\s+потребител|минимальн\w*\s+размер\w*\s+оплат\w*\s+труда|\bмрот\b',
}
CLINICAL=r'диагност|анестези|реанимац|рентген|томограф|ультразвук|терапевт|кардио|пульмо|неврол|невропат|эндокрин|диабет|щитовид|гастро|гинекол|уролог|травм|ортопед|физиотерап|ковид|covid|гипертенз|гипертони|аритми|сердеч|бронх|астм|пневмони|легочн|лёгочн|эпилеп|инсульт|головн.{0,6}бол|мигрен|панкреат|гастрит|кишеч|язвен|гепатит|желч|печен|печён|мочев|почеч|почек|цистит|простат|матки|яичник|эндометри|менстру|перелом|сустав|позвоноч|остео|сахар|ожирен|анем|аппендиц|грыж|реабилитац'
INTERNAL=r'центральн\w*\s+аппарат|государственн\w*\s+гражданск\w*\s+служащ|федеральн\w*\s+государственн\w*\s+орган\w*.{0,60}(?:сайт|доход)|учетн\w*\s+политик\w*.{0,120}(?:минюст|министерств|фнс|фомс|фонд)|положени\w*\s+о\s+департамент|служебн\w*\s+поведен|сведени\w*\s+о\s+доходах.{0,60}об\s+имуществ|кодекс\w*\s+этик\w*\s+и\s+служебн|противодейств\w*\s+коррупц|кадров\w*\s+резерв\w*.{0,80}(?:фонд|министерств)|конкурс\w*.{0,40}замещени\w*\s+должност|закупк\w*.{0,40}(?:канцеляр|служебн\w*\s+автомобил)|расход\w*\s+на\s+содержани\w*\s+(?:аппарат|фонд)'
OFF_TOPIC=r'адвокат|иностранн\w*\s+агент|актов\s+гражданского\s+состояния|уголовн\w*\s+дел|государственной\s+регистрации\s+некоммерческ|образовательн\w*\s+деятельност|детско.{0,3}юношеск\w*\s+спорт|детск\w*\s+сад|строительств\w*\s+школ|школьн\w*\s+питан|межеван|кадастров|автомобильн\w*\s+пункт\w*\s+пропуск|таможенн\w*\s+служб|льготн\w*\s+ипотек|агрострахован|сельскохозяйственн\w*\s+налог|сельхоз|экономическ\w*\s+зон|ветеран\w*\s+боев\w*\s+действ|страхован\w*\s+жизн|негосударственн\w*\s+пенсионн|государственн\w*\s+пошлин.{0,80}(?:адвокат|загс)|шельф|национальн\w*\s+парк|охотнич|рыболов|мобилизован|креативн\w*\s+экономик|социально.{0,3}экономическ\w*\s+развити'
OTHER_REGIONS=r'Тыва|Тув[аеы]|Томск|Ярославск|Брянск|Курганск|Хабаровск|Дальн\w*\s+Восток|Еврейск\w*\s+автономн|Камчат|Крым|Севастопол|Рязанск|Московск\w*\s+област'
TARGETED=r'выдел|направит|финансирован|субсиди|закупк|строительств|списал|задолженност|бюджетн\w*\s+кредит'
GENERIC=r'^(?:скачать(?:\s+\w+|\s*\([^)]*\))?|документ(?:\.[a-z]+|\s+[a-z]+(?:,.*)?)?)$'
ISSUER=r'министерств\w*\s+здравоохранени\w*(?:\s+(?:российской\s+федерации|калужской\s+области))?|федеральн\w*\s+служб\w*\s+по\s+надзор\w*\s+в\s+сфер\w*\s+защит\w*\s+прав\w*\s+потребител\w*\s+и\s+благополуч\w*\s+человек\w*'
ADMIN=r'положени\w*\s+о\s+министерств|график\w*\s+личн\w*\s+при[её]м|главн\w*\s+внештатн\w*\s+специалист|персональн\w*\s+состав|научно.{0,3}практическ\w*.{0,80}(?:конференц|мероприяти|конгресс)|план\w*.{0,80}(?:конференц|конгресс)|санитарн\w*.{0,30}(?:охран|защит)\w*.{0,20}зон\w*.{0,100}(?:анап|сочи|курорт)'
REFERENCE=r'^(?:автоматизированн\w*\s+систем|реестр\s|каталог\s|портал\s|личн\w*\s+кабинет|информационн\w*\s+систем)'
UNCONFIRMED_CLINICAL=r'век\b|конъюнктив|ретинопат|макулярн|трансплантац|отторжен\w*.{0,40}(?:орган|ткан|трансплант)|traps|ассоциированн\w*\s+с\s+рецептор\w*\s+фактор\w*\s+некроз'
MEDICAL_CONTEXT=r'медицинск\w*\s+(?:организац|услуг|работник|персонал|помощ|деятельност|издел)|пациент|врач|лечебн\w*\s+учрежден|здравоохранени|\bомс\b|\bегисз\b|\bфрмр\b|\bфрмо\b|экспертиз\w*\s+(?:временн\w*\s+)?нетрудоспособност|листк\w*\s+нетрудоспособност'
TAX_LABOUR=r'налог|\bусн\b|\bндфл\b|кассов|трудов|выходн|праздничн|рабоч\w*\s+врем|страхов\w*\s+взнос|\bмрот\b|оплат\w*\s+труда|работодател'

def matches(pattern,text):return bool(re.search(pattern,text,re.I))

def should_fetch(title,source):
    """Reject explicit unrelated subjects before downloading; keep unclear acts."""
    evaluation=evaluate(title,'',source)
    return evaluation['relevance']!='other' or evaluation['reason']=='Связь с профилем центра по предмету документа не установлена'

def evaluate(title,text,source):
    title=' '.join((title or '').split())
    sid=source['id']
    def result(scope,topics,reason):return {'relevance':scope,'topics':topics,'reason':reason,'version':VERSION}
    if sid=='tfoms' and matches(r'^Федерального\s+закона\s+№\s*\d+[-–]ФЗ$',title):return result('other',[],'Ссылка на упоминаемый закон в справочном описании работы фонда, а не карточка новой публикации')
    if matches(r'^(?:документаци\w*|дистрибутив\w*|инструкци\w*\s+по\s+установк\w*).{0,60}(?:vipnet|випнет)',title):return result('other',[],'Документация программы, а не новый нормативный акт')
    if matches(INTERNAL,title) or matches(r'главн\w*\s+администратор\w*\s+(?:доход|источник\w*\s+финансирован)',title):return result('other',[],'Внутренние правила государственного органа, а не требования к медицинскому центру')
    if matches(ADMIN,title) or matches(r'санитарн\w*\s+охран\w*\s+курорт\w*.{0,80}(?:анап|сочи)',title):return result('other',[],'Организация работы ведомства или мероприятие вне задач центра')
    if matches(REFERENCE,title):return result('other',[],'Справочный сервис, а не отдельный нормативный документ')
    if matches(OTHER_REGIONS,title) and matches(TARGETED,title) and not matches(r'Калуг|все\w*\s+регион',title):
        return result('other',[],'Адресное решение для другого региона')
    if matches(r'передвижн\w*\s+аптек|стоматолог|одонтоген|челюст|\bзуб(?:ов|а|ы|е|у|ам|ами|н\w*)\b|ветеринар',title):
        return result('other',[],'Направление не подтверждено в профиле центра')
    if matches(OFF_TOPIC,title):return result('other',[],'Предмет документа не относится к подтверждённым задачам центра')
    if matches(r'лицензиру\w*\s+вид\w*\s+деятельност\w*\s+в\s+област\w*\s+пожарн',title):return result('other',[],'Обучение работников специализированных организаций с пожарной лицензией')
    if matches(r'поддержк\w*\s+медицинск\w*\s+работник\w*\s+в\s+сельск',title):return result('review',[],'Адресная поддержка сельских работников; применимость к центру в Калуге не установлена')
    if sid in ('tfoms','ffoms'):
        return result('medical',['ОМС'],'Документ профильного фонда ОМС; внутренние кадровые и ведомственные правила исключены')
    # The issuing authority is not the subject of the act.
    subject=re.sub(ISSUER,' ',title,flags=re.I)
    topics=[name for name,pattern in RULES.items() if matches(pattern,subject)]
    if not topics and matches(TAX_LABOUR,subject):topics.append('Общие требования')
    medical_context=matches(MEDICAL_CONTEXT,subject)
    if medical_context and not any(t!='Общие требования' for t in topics):topics.append('Работа центра')
    if topics==['Общие требования'] and not medical_context and matches(TAX_LABOUR,subject):
        # The owner only wants labour/tax rules with a specific medical scope.
        # Bare amendments to the Tax Code still need the actual subject checked.
        if matches(r'о\s+внесении\s+изменени.{0,100}налогов\w*\s+кодекс',subject):
            lead=' '.join((text or '').split())[:2500]
            if matches(MEDICAL_CONTEXT,lead) and matches(r'льгот|освобожден|налогооблож|медицинск\w*\s+услуг',lead):
                return result('medical',['Работа центра'],'Налоговые изменения специально для медицинской деятельности в начале текста')
            return result('review' if not text else 'other',[],'Налоговые изменения: специальная связь с медициной не подтверждена')
        return result('other',[],'Общие трудовые или налоговые требования без специальной связи с медициной')
    if sid=='clinrec':
        if matches(UNCONFIRMED_CLINICAL,title) or matches(r'новорожд[её]н|неонат',title):return result('review',[],'Клиническая рекомендация по специальности, не подтверждённой у центра')
        if matches(CLINICAL,subject):return result('medical',list(dict.fromkeys(topics+['Работа центра'])),'Клиническая рекомендация по диагностике или специальностям центра')
        return result('review',[],'Профиль клинической рекомендации не подтверждён по названию')
    # Children alone are not medical evidence: school/sport/benefit acts never qualify.
    if topics:
        if matches(r'детей|детям|детск|реб[её]н|педиатр',title) and any(t in topics for t in ('Работа центра','ОМС','МРТ / КТ','Наркоз','Анализы')):topics.append('Дети')
        return result('medical',list(dict.fromkeys(topics)),'Предмет акта в названии связан с задачами центра: '+', '.join(topics))
    if matches(r'санпин|санитарн\w*\s+правил|санитарно.{0,3}эпидемиологическ',title):
        if matches(r'медицин|лечебн|рентген|радиац|дезинфек|инфекционн\w*\s+безопасност|отход',title):return result('medical',['Работа центра'],'Санитарные требования к медицинской деятельности')
        return result('review',[],'Санитарный акт: применимость к центру нужно уточнить')
    # Full informative titles take precedence over keywords scattered in an appendix.
    informative=matches(r'\bоб?\s+[а-яё]',title) and not matches(r'\bо\s+(?:внесении\s+изменени|признании\s+утративш|приостановлении)',title)
    if not informative and text:
        # Only the beginning of the document: not footer, references or the whole attachment.
        lead=re.sub(ISSUER,' ',' '.join(text.split())[:1800],flags=re.I)
        if not matches(INTERNAL,lead) and not matches(OFF_TOPIC,lead):
            medical=[name for name in ('ОМС','МРТ / КТ','Наркоз','Дневной стационар','Анализы','Работа центра') if matches(RULES[name],lead)]
            if medical:return result('medical',medical,'Связь с медицинской деятельностью в начале текста документа')
    if source.get('medical') or matches(r'санпин|лиценз|профессиональн\w*\s+стандарт',title):
        return result('review',[],'Нет достаточного описания предмета; отдельно на ручную проверку')
    if not informative and not text and matches(r'приказ|постановлен|распоряжен|закон|'+GENERIC,title):
        return result('review',[],'Документ без раскрытого предмета; применимость пока не установлена')
    return result('other',[],'Связь с профилем центра по предмету документа не установлена')
